/**
 * Environmental Acoustic Engine for Data Center Siting and Noise Mitigation
 * Implements ISO 9613-2 outdoor propagation, Maekawa barrier diffraction,
 * subterranean vault attenuation, and species-specific bio-acoustic buffering.
 */

import { REGIONAL_TREE_SPECIES, WALL_MATERIALS } from "./datacenterSites.js";

/**
 * Calculates the raw Sound Power Level (Lw in dBA) generated by the outdoor
 * cooling plant (chillers, cooling towers, and condenser fans) as a function of
 * IT compute load and outdoor ambient temperature.
 *
 * @param {number} itPowerKw - Total IT compute load in kilowatts
 * @param {number} ambientTempC - Ambient outdoor temperature in Celsius
 * @param {number} fanSpeedPercent - Chiller condenser fan speed percentage (0 - 100)
 * @returns {number} Sound Power Level (Lw) in dBA at source
 */
export function calculateChillerSoundPower(itPowerKw = 500, ambientTempC = 22, fanSpeedPercent = 75) {
  // Baseline industrial multi-chiller plant generates ~108 dBA sound power level (Lw)
  // at nominal 20°C ambient and 70% fan speed across a 3-unit condenser array
  const baselineLw = 108.0;

  // Temperature penalty: Higher ambient temp raises condenser lift and compressor load
  // Every 5°C above 20°C adds ~1.2 dBA of fan and compressor acoustic stress
  const tempDelta = Math.max(0, ambientTempC - 20);
  const tempAcousticPenalty = (tempDelta / 5) * 1.2;

  // Fan speed scaling: Fan acoustic noise scales with the 5th power of tip speed (L ~ 50 log10(RPM))
  // Normalized between 40% and 100% fan duty
  const normalizedFan = Math.max(0.3, fanSpeedPercent / 100);
  const fanAcousticContribution = 18 * Math.log10(normalizedFan / 0.7);

  // Compute load scaling: Higher IT load increases active compressor stages
  const loadScaling = 10 * Math.log10(Math.max(100, itPowerKw) / 500);

  return Math.max(82, baselineLw + tempAcousticPenalty + fanAcousticContribution + loadScaling);
}

/**
 * Calculates acoustic insertion loss (attenuation in dB) from an acoustic barrier wall.
 * Implements Maekawa / Kurze-Anderson barrier diffraction with material absorption (NRC).
 *
 * @param {number} wallHeightMeters - Height of barrier wall in meters (2m - 16m)
 * @param {string} materialId - Material key from WALL_MATERIALS
 * @param {number} sourceDistanceM - Distance from chiller to wall (meters)
 * @param {number} receiverDistanceM - Distance from wall to residential receptor (meters)
 * @param {boolean} wallEnabled - Whether the wall is active
 * @returns {{ attenuationDb: number, costEstimate: number, embodiedCarbonKg: number }}
 */
export function calculateWallAttenuation(
  wallHeightMeters = 8,
  materialId = "absorptive_metal",
  sourceDistanceM = 15,
  receiverDistanceM = 300,
  wallEnabled = true
) {
  if (!wallEnabled || wallHeightMeters <= 0) {
    return { attenuationDb: 0, costEstimate: 0, embodiedCarbonKg: 0 };
  }

  const material = WALL_MATERIALS[materialId] || WALL_MATERIALS.absorptive_metal;

  // Effective path difference (delta) over the top of the barrier:
  // Assumes chiller source height = 3.5m, receptor ear height = 1.8m
  const sourceHeight = 3.5;
  const receptorHeight = 1.8;
  const effectiveWallHeight = Math.max(0.5, wallHeightMeters);

  const h1 = Math.max(0.1, effectiveWallHeight - sourceHeight);
  const h2 = Math.max(0.1, effectiveWallHeight - receptorHeight);

  // Line of sight distance without barrier
  const directDistance = Math.hypot(receiverDistanceM + sourceDistanceM, Math.abs(sourceHeight - receptorHeight));

  // Diffracted path distance over barrier
  const diffractedPath = Math.hypot(sourceDistanceM, h1) + Math.hypot(receiverDistanceM, h2);
  const deltaPath = Math.max(0, diffractedPath - directDistance);

  // Dominant wavelength for 120 Hz chiller hum is ~2.86m
  const lambda = 2.86;
  const fresnelN = (2 * deltaPath) / lambda;

  // Maekawa insertion loss formula: A_bar = 10 * log10(3 + 20 * N)
  let rawBarrierLoss = 10 * Math.log10(Math.max(1, 3 + 20 * fresnelN));

  // Cap single diffraction barrier loss at practical limit (24 dB due to atmospheric scattering)
  rawBarrierLoss = Math.min(24, rawBarrierLoss);

  // Material Absorption Adjustment:
  // Absorptive materials (high NRC) prevent sound reflections from spilling over the lip
  // Reflective concrete without absorptive treatment loses ~2.5 dB due to yard reverberation
  const absorptionBonus = material.nrcRating >= 0.8 ? 2.5 : material.nrcRating >= 0.5 ? 1.0 : -1.5;

  const finalAttenuation = Math.max(2.0, Math.min(26.0, rawBarrierLoss + absorptionBonus));

  // Perimeter length around typical chiller yard: ~90 meters
  const wallPerimeterMeters = 90;
  const wallAreaSqMeters = wallPerimeterMeters * wallHeightMeters;
  const costEstimate = wallAreaSqMeters * material.costPerSqMeter;
  const embodiedCarbonKg = wallAreaSqMeters * material.embodiedCarbonKgPerSqMeter;

  return {
    attenuationDb: Math.round(finalAttenuation * 10) / 10,
    costEstimate: Math.round(costEstimate),
    embodiedCarbonKg: Math.round(embodiedCarbonKg),
  };
}

/**
 * Calculates bio-acoustic attenuation provided by a native vegetation buffer zone.
 * Based on ISO 9613-2 foliage scattering + porous soil ground effect.
 *
 * @param {number} bufferDepthMeters - Depth of the planted tree buffer in meters (0 - 80m)
 * @param {string} treeSpeciesId - Tree key from REGIONAL_TREE_SPECIES
 * @param {boolean} treeEnabled - Whether the tree buffer is active
 * @returns {{ attenuationDb: number, annualMaintenanceCost: number, annualWaterGallons: number, annualCo2Kg: number }}
 */
export function calculateVegetationAttenuation(
  bufferDepthMeters = 25,
  treeSpeciesId = "virginia_pine",
  treeEnabled = true
) {
  if (!treeEnabled || bufferDepthMeters <= 0) {
    return {
      attenuationDb: 0,
      annualMaintenanceCost: 0,
      annualWaterGallons: 0,
      annualCo2Kg: 0,
    };
  }

  const species = REGIONAL_TREE_SPECIES[treeSpeciesId] || REGIONAL_TREE_SPECIES.virginia_pine;

  // Foliage scattering increases with depth, but saturates asymptotically
  // ISO 9613-2 limits foliage attenuation to ~10 - 12 dB because sound creeps over treetops
  const rawAttenuation = species.acousticAbsorptionCoeff * bufferDepthMeters;
  const saturatedAttenuation = 12 * (1 - Math.exp(-rawAttenuation / 10));

  // Ground effect bonus: Tree roots, humus, and leaf litter convert hard acoustic ground
  // into an acoustic porous sponge (eliminating ground bounce reflection)
  const porousGroundBonus = bufferDepthMeters >= 10 ? 2.5 : (bufferDepthMeters / 10) * 2.5;

  const totalAttenuation = Math.min(14.0, saturatedAttenuation + porousGroundBonus);

  // Environmental & Cost metrics across an 80m wide parcel buffer
  const bufferWidthMeters = 80;
  const bufferAreaSqMeters = bufferWidthMeters * bufferDepthMeters;
  const estimatedTreeCount = Math.round(bufferAreaSqMeters / 9); // ~1 tree per 9m² (3m spacing)

  const annualMaintenanceCost = bufferDepthMeters * species.annualMaintenanceCostPerMeter;
  const annualWaterGallons = Math.round((bufferAreaSqMeters / 4046) * species.annualWaterGallonsPerAcre);
  const annualCo2Kg = estimatedTreeCount * species.co2AbsorptionKgPerTreePerYear;

  return {
    attenuationDb: Math.round(totalAttenuation * 10) / 10,
    annualMaintenanceCost: Math.round(annualMaintenanceCost),
    annualWaterGallons,
    annualCo2Kg: Math.round(annualCo2Kg),
  };
}

/**
 * Calculates subterranean / earth placement attenuation.
 *
 * @param {"surface" | "semi_berm" | "underground"} placement
 * @returns {{ attenuationDb: number, capexMultiplier: number, thermalPuePenalty: number }}
 */
export function calculatePlacementAttenuation(placement = "side_exposed") {
  switch (placement) {
    case "underground":
      return {
        attenuationDb: 28.0, // Massive line-of-sight blockage; only muffled intake/exhaust stacks remain
        capexMultiplier: 2.8, // Excavation and waterproof vault costs
        thermalPuePenalty: 0.04, // Slightly higher fan power to overcome ventilation duct resistance
        description: "Subterranean Bunker Vault: Chillers placed 6m underground with vertical acoustic silencers.",
      };
    case "rear_shielded":
      return {
        attenuationDb: 18.0, // Building acoustic shadow (massive 12m data center core blocks line-of-sight)
        capexMultiplier: 1.05, // Standard ground installation with extended pipe runs
        thermalPuePenalty: 0.0,
        description: "Rear Yard (Building-Shielded): Uses the 12m windowless data center building as a physical sound shield.",
      };
    case "semi_berm":
      return {
        attenuationDb: 11.5, // 3m recessed pit surrounded by earth berms
        capexMultiplier: 1.4,
        thermalPuePenalty: 0.01,
        description: "Semi-Bermed Basin: Chillers recessed 3m with sloped earthen acoustic berms.",
      };
    case "rooftop":
      return {
        attenuationDb: -3.5, // Line-of-sight elevation penalty; sound radiates widely over fences and foliage
        capexMultiplier: 1.25, // Roof structural reinforcement and spring/inertia vibration isolation
        thermalPuePenalty: 0.0,
        description: "Rooftop Chiller Penthouse: Elevated on 12m roof deck. Eliminates land footprint but radiates sound over ground buffers.",
      };
    case "side_exposed":
    case "surface":
    default:
      return {
        attenuationDb: 0.0,
        capexMultiplier: 1.0,
        thermalPuePenalty: 0.0,
        description: "Side Yard (Exposed): Standard ground yard facing property line without building shielding.",
      };
  }
}

/**
 * Master acoustic simulation calculation for a data center site.
 * Combines distance decay, placement, barrier walls, vegetation, orientation, and terrain.
 *
 * @param {Object} params
 * @returns {Object} Comprehensive acoustic results, compliance status, and breakdown
 */
export function evaluateSiteAcoustics({
  itPowerKw = 500,
  ambientTempC = 22,
  fanSpeedPercent = 75,
  distanceToHomesMeters = 320,
  municipalNoiseLimitDba = 45,
  daytimeNoiseLimitDba = 55,
  timeOfDay = "night", // "day" | "night"
  terrainEchoDb = 0.0,
  chillerPlacement = "surface",
  wallHeightMeters = 8,
  wallMaterial = "absorptive_metal",
  wallEnabled = true,
  wallEnclosure = "single_east", // "single_east" | "u_shape" | "full_4side"
  treeBufferDepthMeters = 25,
  treeSpeciesId = "virginia_pine",
  treeEnabled = true,
  treeArrangement = "east_buffer", // "east_buffer" | "perimeter_ring"
  chillerOrientationAngle = 90, // Degrees away from residential zone (0 - 180)
  acousticSilencers = false, // High-performance compressor sound blankets & intake silencers
}) {
  // 1. Source Sound Power Level
  let rawSourceLw = calculateChillerSoundPower(itPowerKw, ambientTempC, fanSpeedPercent);
  if (acousticSilencers) {
    rawSourceLw -= 5.5; // Acoustic silencers and compressor blankets
  }
  const sourceLw = rawSourceLw;

  // 2. Free-field Geometric Distance Spreading (ISO 9613-2 hemispherical point source)
  // Lp_free = Lw - 20 * log10(d) - 11
  const effectiveDistance = Math.max(10, distanceToHomesMeters);
  const geometricDecay = 20 * Math.log10(effectiveDistance) + 11.0;

  // 3. Atmospheric and Day/Night Inversion effects:
  // At night, cool air near the ground and warm air aloft causes a thermal inversion,
  // bending acoustic waves back down toward the ground (+1.8 dB propagation boost).
  // In the daytime, solar heating creates upward lapse, attenuating sound (-1.2 dB).
  const atmosphericInversionDb = timeOfDay === "night" ? 1.8 : -1.2;

  // Unmitigated sound level at receiver
  const unmitigatedLp = Math.max(30, sourceLw - geometricDecay + terrainEchoDb + atmosphericInversionDb);

  // 4. Mitigations
  const placementData = calculatePlacementAttenuation(chillerPlacement);
  const wallData = calculateWallAttenuation(wallHeightMeters, wallMaterial, 15, effectiveDistance, wallEnabled);
  const treeData = calculateVegetationAttenuation(treeBufferDepthMeters, treeSpeciesId, treeEnabled);

  // Enclosure bonus: U-shape or 4-sided enclosure traps sound
  let enclosureBonus = 0;
  if (wallEnabled && wallHeightMeters >= 4) {
    if (wallEnclosure === "full_4side") enclosureBonus = 3.5;
    else if (wallEnclosure === "u_shape") enclosureBonus = 2.0;
  }

  // Directivity attenuation: Directing louvers/exhaust 90° - 180° away from homes gives 2 - 5 dB
  const directivityAttenuation = (chillerOrientationAngle / 180) * 4.5;

  // Total Mitigated Attenuation:
  // When underground, wall and directivity have diminishing marginal returns
  let effectiveWallAtten = wallData.attenuationDb + enclosureBonus;
  let effectiveDirectivity = directivityAttenuation;
  if (chillerPlacement === "underground") {
    effectiveWallAtten *= 0.25; // Wall mostly shields remaining exhaust stack
    effectiveDirectivity *= 0.5;
  } else if (chillerPlacement === "semi_berm") {
    effectiveWallAtten *= 0.85;
  }

  const totalMitigationDb =
    placementData.attenuationDb +
    effectiveWallAtten +
    treeData.attenuationDb +
    effectiveDirectivity;

  // 5. Ambient Background Noise Floor & Time-of-Day Law:
  // Day ambient: ~50-52 dBA (arterial traffic, lawnmowers, birds, human bustle)
  // Night ambient: ~30-32 dBA (quiet nocturnal suburban calm)
  const backgroundNoiseFloor = timeOfDay === "day" ? 52.0 : 32.0;
  const activeLegalLimit = timeOfDay === "day" ? (daytimeNoiseLimitDba || municipalNoiseLimitDba + 10) : municipalNoiseLimitDba;

  const rawReceivedLp = sourceLw - geometricDecay + terrainEchoDb + atmosphericInversionDb - totalMitigationDb;
  const netReceivedLp = 10 * Math.log10(10 ** (backgroundNoiseFloor / 10) + 10 ** (Math.max(15, rawReceivedLp) / 10));

  // Signal-to-Noise Ratio (SNR) above ambient
  const snrAboveAmbient = Math.max(0, rawReceivedLp - backgroundNoiseFloor);

  // Compliance analysis
  const marginDb = activeLegalLimit - netReceivedLp;
  const isCompliant = marginDb >= 0;

  // Severity category
  let complianceStatus = "Compliant";
  let statusColor = "#34d399"; // Green
  if (marginDb < -10) {
    complianceStatus = "Severe Violation";
    statusColor = "#ef4444"; // Red
  } else if (marginDb < 0) {
    complianceStatus = "Noise Violation";
    statusColor = "#f97316"; // Orange
  } else if (marginDb < 3) {
    complianceStatus = "Marginal Compliance";
    statusColor = "#eab308"; // Yellow
  }

  // Low-frequency tonal hum (dBC):
  const lowFreqBonus =
    chillerPlacement === "underground"
      ? 5.0
      : chillerPlacement === "rear_shielded"
      ? 9.5
      : 14.5;
  const netReceivedLpC = Math.round((netReceivedLp + lowFreqBonus) * 10) / 10;
  const lowFreqExcess = Math.round((netReceivedLpC - netReceivedLp) * 10) / 10;

  return {
    sourceLw: Math.round(sourceLw * 10) / 10,
    unmitigatedLp: Math.round(unmitigatedLp * 10) / 10,
    netReceivedLp: Math.round(netReceivedLp * 10) / 10,
    netReceivedLpC,
    lowFreqExcess,
    noiseReductionDb: Math.round((unmitigatedLp - netReceivedLp) * 10) / 10,
    municipalNoiseLimitDba: activeLegalLimit,
    activeLegalLimit,
    timeOfDay,
    backgroundNoiseFloor,
    snrAboveAmbient: Math.round(snrAboveAmbient * 10) / 10,
    marginDb: Math.round(marginDb * 10) / 10,
    isCompliant,
    complianceStatus,
    statusColor,
    breakdown: {
      geometricDecay: Math.round(geometricDecay * 10) / 10,
      terrainEchoDb: Math.round(terrainEchoDb * 10) / 10,
      inversionEffect: Math.round(atmosphericInversionDb * 10) / 10,
      placementAttenuation: Math.round(placementData.attenuationDb * 10) / 10,
      wallAttenuation: Math.round(effectiveWallAtten * 10) / 10,
      treeAttenuation: Math.round(treeData.attenuationDb * 10) / 10,
      directivityAttenuation: Math.round(effectiveDirectivity * 10) / 10,
      totalMitigationDb: Math.round(totalMitigationDb * 10) / 10,
    },
    economics: {
      wallCostEstimate: wallData.costEstimate * (wallEnclosure === "full_4side" ? 2.5 : wallEnclosure === "u_shape" ? 1.8 : 1.0),
      wallEmbodiedCarbonKg: wallData.embodiedCarbonKg * (wallEnclosure === "full_4side" ? 2.5 : wallEnclosure === "u_shape" ? 1.8 : 1.0),
      treeAnnualMaintenanceCost: treeData.annualMaintenanceCost * (treeArrangement === "perimeter_ring" ? 2.2 : 1.0),
      treeAnnualWaterGallons: treeData.annualWaterGallons * (treeArrangement === "perimeter_ring" ? 2.2 : 1.0),
      treeAnnualCo2Kg: treeData.annualCo2Kg * (treeArrangement === "perimeter_ring" ? 2.2 : 1.0),
      capexMultiplier: placementData.capexMultiplier,
    },
  };
}

/**
 * Calculates noise level at an arbitrary probe distance in meters.
 */
export function calculateNoiseAtPoint({
  probeDistanceMeters = 100,
  itPowerKw = 500,
  ambientTempC = 22,
  fanSpeedPercent = 75,
  terrainEchoDb = 0.0,
  chillerPlacement = "surface",
  wallHeightMeters = 8,
  wallMaterial = "absorptive_metal",
  wallEnabled = true,
  wallEnclosure = "single_east",
  treeBufferDepthMeters = 25,
  treeSpeciesId = "virginia_pine",
  treeEnabled = true,
  chillerOrientationAngle = 90,
  municipalNoiseLimitDba = 45,
  timeOfDay = "night",
  acousticSilencers = false,
}) {
  const d = Math.max(2, probeDistanceMeters);
  let rawSourceLw = calculateChillerSoundPower(itPowerKw, ambientTempC, fanSpeedPercent);
  if (acousticSilencers) rawSourceLw -= 5.5;
  const sourceLw = rawSourceLw;

  const geometricDecay = 20 * Math.log10(d) + 11.0;
  const atmosphericInversionDb = timeOfDay === "night" ? 1.8 : -1.2;

  // Evaluate mitigations
  const placementData = calculatePlacementAttenuation(chillerPlacement);
  const wallData = calculateWallAttenuation(wallHeightMeters, wallMaterial, 15, d, wallEnabled);
  const treeData = calculateVegetationAttenuation(treeBufferDepthMeters, treeSpeciesId, treeEnabled);
  const directivityAttenuation = (chillerOrientationAngle / 180) * 4.5;

  let enclosureBonus = 0;
  if (wallEnabled && wallHeightMeters >= 4) {
    if (wallEnclosure === "full_4side") enclosureBonus = 3.5;
    else if (wallEnclosure === "u_shape") enclosureBonus = 2.0;
  }

  let effectiveWallAtten = wallData.attenuationDb + enclosureBonus;
  let effectiveDirectivity = directivityAttenuation;
  if (chillerPlacement === "underground") {
    effectiveWallAtten *= 0.25;
    effectiveDirectivity *= 0.5;
  } else if (chillerPlacement === "semi_berm") {
    effectiveWallAtten *= 0.85;
  }

  // If probe is closer than wall (e.g. < 15m), wall doesn't attenuate
  if (d < 18) {
    effectiveWallAtten = 0;
  }
  // If probe is closer than tree buffer (e.g. < 25m), trees don't attenuate
  if (d < 25) {
    treeData.attenuationDb = 0;
  }

  const totalMitigationDb =
    placementData.attenuationDb +
    effectiveWallAtten +
    treeData.attenuationDb +
    effectiveDirectivity;

  const backgroundNoiseFloor = timeOfDay === "day" ? 52.0 : 32.0;
  const rawReceivedLp = sourceLw - geometricDecay + terrainEchoDb + atmosphericInversionDb - totalMitigationDb;
  const netReceivedLp = 10 * Math.log10(10 ** (backgroundNoiseFloor / 10) + 10 ** (Math.max(15, rawReceivedLp) / 10));

  const marginDb = municipalNoiseLimitDba - netReceivedLp;
  const isCompliant = marginDb >= 0;

  const lowFreqBonus =
    chillerPlacement === "underground"
      ? 5.0
      : chillerPlacement === "rear_shielded"
      ? 9.5
      : 14.5;
  const netReceivedLpC = Math.round((netReceivedLp + lowFreqBonus) * 10) / 10;

  let sensation = "Quiet Environment";
  if (netReceivedLp > 75) sensation = "Intense Plant Machinery Roar";
  else if (netReceivedLp > 65) sensation = "Loud Industrial Compressor Noise";
  else if (netReceivedLp > 50) sensation = "Audible Continuous Hum";
  else if (netReceivedLp > 42) sensation = "Low Background Whine";
  else sensation = "Quiet Sleep Sanctuary (Compliant)";

  return {
    distanceMeters: Math.round(d),
    netDba: Math.round(netReceivedLp * 10) / 10,
    netDbc: netReceivedLpC,
    marginDb: Math.round(marginDb * 10) / 10,
    isCompliant,
    sensation,
  };
}

/**
 * Calculates isophone radii (meters) for concentric noise circles.
 */
export function calculateIsophoneRadii({
  targetDbaLevels = [75, 65, 55, 45, 40],
  itPowerKw = 500,
  ambientTempC = 22,
  fanSpeedPercent = 75,
  terrainEchoDb = 0.0,
  chillerPlacement = "surface",
  wallHeightMeters = 8,
  wallMaterial = "absorptive_metal",
  wallEnabled = true,
  wallEnclosure = "single_east",
  treeBufferDepthMeters = 25,
  treeSpeciesId = "virginia_pine",
  treeEnabled = true,
  chillerOrientationAngle = 90,
  timeOfDay = "night",
  acousticSilencers = false,
}) {
  let rawSourceLw = calculateChillerSoundPower(itPowerKw, ambientTempC, fanSpeedPercent);
  if (acousticSilencers) rawSourceLw -= 5.5;
  const sourceLw = rawSourceLw;
  const atmosphericInversionDb = timeOfDay === "night" ? 1.8 : -1.2;

  const placementData = calculatePlacementAttenuation(chillerPlacement);
  const wallData = calculateWallAttenuation(wallHeightMeters, wallMaterial, 15, 300, wallEnabled);
  const treeData = calculateVegetationAttenuation(treeBufferDepthMeters, treeSpeciesId, treeEnabled);
  const directivityAttenuation = (chillerOrientationAngle / 180) * 4.5;

  let enclosureBonus = 0;
  if (wallEnabled && wallHeightMeters >= 4) {
    if (wallEnclosure === "full_4side") enclosureBonus = 3.5;
    else if (wallEnclosure === "u_shape") enclosureBonus = 2.0;
  }

  let effectiveWallAtten = wallData.attenuationDb + enclosureBonus;
  let effectiveDirectivity = directivityAttenuation;
  if (chillerPlacement === "underground") {
    effectiveWallAtten *= 0.25;
    effectiveDirectivity *= 0.5;
  } else if (chillerPlacement === "semi_berm") {
    effectiveWallAtten *= 0.85;
  }

  const totalMitigationDb =
    placementData.attenuationDb +
    effectiveWallAtten +
    treeData.attenuationDb +
    effectiveDirectivity;

  return targetDbaLevels.map((targetDba) => {
    // d = 10^((Lw - 11 + terrainEcho + atmosphericInversion - totalMitigation - targetDba) / 20)
    const exponent = (sourceLw - 11.0 + terrainEchoDb + atmosphericInversionDb - totalMitigationDb - targetDba) / 20.0;
    const radiusMeters = Math.max(3, Math.min(1200, Math.pow(10, exponent)));
    return {
      targetDba,
      radiusMeters: Math.round(radiusMeters),
    };
  });
}
